import{_ as d,l as i,o as a,c as l,v as t,p as n,x as r,d as s,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"线程化分派","description":"","frontmatter":{"title":"线程化分派","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/threaded-dispatch.md","filePath":"cs/threaded-dispatch.md","lastUpdated":1789023840000}'),p={name:"cs/threaded-dispatch.md"};function _(m,e,u,f,T,E){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="线程化分派" tabindex="-1">线程化分派 <a class="header-anchor" href="#线程化分派" aria-label="Permalink to &quot;线程化分派&quot;">​</a></h1><div class="epigraph"><p>把下一条字节码的处理地址直接写进流：间接跳转到该地址，而不是每次回到中央 `switch`。减少分派的间接预测失败。</p><footer>—— 据 Ertl and Gregg, The Structure and Performance of Efficient Interpreters；Bell, Threaded Code, 1973 整理</footer></div><p>上一课<a href="/cs/stack-vs-register-vm">栈式对寄存器式</a> 选了编码。缺口是<strong>分派</strong>：<code>switch</code> 每个 case 后跳回循环头，分支预测惨。线程化：computed goto（GCC 标签作值），每条 handler 末尾 <code>goto *pc++</code>。本课钉 indirect threading / direct / context threading，不写 JIT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解释器热路径是分派，不是加法本身。线程化把「取下一条入口」变成间接跳。缺口是<strong>控制流形状</strong>，不是操作数编码。</p><p>直接线程：指令流就是地址数组。间接：操作码仍是字节，经表变地址。Token threaded：折中。</p><h3 id="线程化不是操作系统线程" tabindex="-1">线程化不是操作系统线程 <a class="header-anchor" href="#线程化不是操作系统线程" aria-label="Permalink to &quot;线程化不是操作系统线程&quot;">​</a></h3><p>名字来自「用地址串起来」。与 pthread 无关。不要混。</p><p><span class="marginnote">Bell 1973。Ertl–Gregg。Forth 传统。C 的 <code>goto *</code> 是 GNU 扩展，可移植要用跳表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：<code>void* table[256]</code>；handler 末 <code>goto *table[*pc++]</code>。超级指令：把高频对（load+add）合成一 handler，减分派次数——与<a href="/cs/inlining-heuristics">内联</a> 同思想在解释器里。</p>',11)),(a(),n(h,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22%E6%93%8D%E4%BD%9C%E7%A0%81%22%5D%20--%3E%20TBL%5B%22%E5%85%A5%E5%8F%A3%E8%A1%A8%22%5D%0A%20%20TBL%20--%3E%20H%5B%22handler%22%5D%0A%20%20H%20--%3E%20NEXT%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%E4%B8%8B%E4%B8%80%E6%9D%A1%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 PGO：按轮廓选超级指令。与 JIT：热点仍编译，冷路径留线程化解释。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>间接跳仍难预测，但比「都跳回同一 switch」好。代码体积：handler 复制。调试：PC 仍要可映射源。</p><p>不要在 handler 里调用会改变栈对齐的未知函数而不保存 VM 状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写方法 JIT。后课默认：高效解释器用线程化分派。下一课方法 JIT 与热点。</p><p>也不把线程化当 GPU warp。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线程化：handler 末间接跳，去掉中央 switch。</li><li>超级指令减分派。</li><li>仍是解释器，不是 native 编译。</li><li>出处：Bell, 1973；Ertl and Gregg。</li></ul>',9))])}const P=d(p,[["render",_]]);export{B as __pageData,P as default};
